    """Return the shortest legal sequence that measures ``goal`` liters."""
    if start_bucket not in {"one", "two"}:
        raise ValueError("start_bucket must be 'one' or 'two'")
    if bucket_one <= 0 or bucket_two <= 0:
        raise ValueError("bucket sizes must be positive")
    if bucket_one == bucket_two:
        raise ValueError("bucket sizes must be different")
    if goal <= 0 or goal > max(bucket_one, bucket_two):
        raise ValueError("goal cannot be measured with these buckets")
    if goal % gcd(bucket_one, bucket_two):
        raise ValueError("goal cannot be measured with these buckets")

    initial = (bucket_one, 0) if start_bucket == "one" else (0, bucket_two)
    forbidden = (
        (0, bucket_two) if start_bucket == "one" else (bucket_one, 0)
    )

    queue = deque([(initial, 1)])
    visited = {initial}

    while queue:
        (amount_one, amount_two), actions = queue.popleft()

        if amount_one == goal:
            return actions, "one", amount_two
        if amount_two == goal:
            return actions, "two", amount_one

        poured_to_two = min(amount_one, bucket_two - amount_two)
        poured_to_one = min(amount_two, bucket_one - amount_one)
        next_states = (
            (amount_one - poured_to_two, amount_two + poured_to_two),
            (amount_one + poured_to_one, amount_two - poured_to_one),
            (bucket_one, amount_two),
            (amount_one, bucket_two),
            (0, amount_two),
            (amount_one, 0),
        )

        for state in next_states:
            if state == (amount_one, amount_two):
                continue
            if state == forbidden or state in visited:
                continue
            visited.add(state)
            queue.append((state, actions + 1))

